// Extraer solo datos relevantes de producto Amazon para seguimiento de precios

const items = $input.all();

return items.map(item => {
    const raw = item.json;

    // === Extracción inteligente del nombre del producto ===
    let productName = raw.title 
        || raw.productTitle 
        || raw.name 
        || (raw.productOverview && typeof raw.productOverview === 'object' ? 'Producto Amazon' : 'Sin nombre');

    // Si el nombre está muy largo, lo acortamos un poco para Telegram
    if (productName.length > 120) {
        productName = productName.substring(0, 117) + '...';
    }

    // === Extracción del precio actual ===
    let currentPrice = null;
    let currency = 'USD';

    if (raw.price) {
        if (typeof raw.price === 'number') {
            currentPrice = raw.price;
        } else if (typeof raw.price === 'object' && raw.price.value !== undefined) {
            currentPrice = raw.price.value;
            currency = raw.price.currency || currency;
        } else if (typeof raw.price === 'string') {
            // Intentar extraer número de string como "$1,299.99"
            const match = raw.price.match(/[\d.,]+/);
            if (match) currentPrice = parseFloat(match[0].replace(/,/g, ''));
        }
    }

    // Alternativas comunes en algunos scrapers
    if (currentPrice === null) {
        currentPrice = raw.currentPrice || raw.priceValue || raw.listPrice || null;
    }

    // === Datos adicionales útiles ===
    const asin = raw.asin || raw.ASIN || raw.variantAsins?.[0] || 'N/A';
    const url = raw.url || raw.productUrl || raw.link || `https://www.amazon.com/dp/${asin}`;

    // Guardamos también el precio formateado para mostrar bonito
    const priceFormatted = currentPrice !== null 
        ? `${currency} ${currentPrice.toLocaleString()}` 
        : 'No disponible';

    return {
        json: {
            // Datos limpios y esenciales
            productName: productName,
            currentPrice: currentPrice,
            priceFormatted: priceFormatted,
            asin: asin,
            url: url,
            currency: currency,

            // Guardamos el raw completo por si necesitas debuggear después
            rawData: raw,

            // Timestamp para saber cuándo se scrapeo
            scrapedAt: new Date().toISOString()
        }
    };
});

