// === Seguimiento de precio Amazon - Versión sin staticData ===

const item = $input.first();
const data = item.json || {};

const productName = data.productName || "Producto desconocido";
const currentPrice = parseFloat(data.currentPrice) || null;
const url = data.url || "#";
const asin = data.asin || "N/A";

if (!currentPrice || isNaN(currentPrice)) {
    return [{
        json: {
            error: "No se detectó precio válido",
            productName: productName,
            currentPrice: null
        }
    }];
}

// === Aquí guardaremos el precio anterior (por ahora usamos un fallback simple) ===
let previousPrice = currentPrice;   // Valor por defecto

// Intento de leer precio anterior desde el item (si viene de un nodo anterior)
if (data.previousPrice !== undefined) {
    previousPrice = parseFloat(data.previousPrice);
}

// Si quieres persistencia real, recomiendo Google Sheets (ver abajo)

// Calcular cambios
const priceChanged = Math.abs(currentPrice - previousPrice) > 0.5;
const percentChange = previousPrice > 0 
    ? ((currentPrice - previousPrice) / previousPrice * 100).toFixed(2) 
    : "0.00";

const isPriceLower = currentPrice < previousPrice - 0.5;
const isPriceHigher = currentPrice > previousPrice + 0.5;

// Mensaje para Telegram
let alertMessage = `📊 Precio actual: $${currentPrice.toFixed(2)}\nProducto: ${productName}\nEnlace: ${url}`;

if (isPriceLower) {
    alertMessage = `✅ ¡Bajó el precio!\n\n` +
                   `Producto: ${productName}\n` +
                   `Anterior: $${previousPrice.toFixed(2)}\n` +
                   `Actual: $${currentPrice.toFixed(2)}\n` +
                   `↓ Bajó ${percentChange}%\n\n` +
                   `Enlace → ${url}`;
} else if (isPriceHigher) {
    alertMessage = `⚠️ Precio subió\n\n` +
                   `Producto: ${productName}\n` +
                   `Anterior: $${previousPrice.toFixed(2)}\n` +
                   `Actual: $${currentPrice.toFixed(2)}\n` +
                   `↑ Subió ${percentChange}%\n\n` +
                   `Enlace → ${url}`;
}

return [{
    json: {
        productName,
        currentPrice,
        previousPrice,
        percentChange,
        isPriceLower,
        isPriceHigher,
        priceChanged,
        alertMessage,
        url,
        asin,
        scrapedAt: new Date().toISOString()
    }
}];

// === Save Current Price - Versión simple y estable ===
// Solo guarda el precio actual en el item para que el siguiente nodo lo use

const item = $input.first();
const data = item.json;

const currentPrice = parseFloat(data.currentPrice) || null;
const asin = data.asin || "B0F93FMYD5";
const productName = data.productName || "Redragon K742";

if (!currentPrice) {
    return [{ json: { error: "No current price found" } }];
}

// Simplemente devolvemos el precio actual como "previousPrice" para la próxima ejecución
// (En la práctica, usaremos Google Sheets o un Merge más adelante)

return [{
    json: {
        status: "Price saved for next run",
        currentPrice: currentPrice,
        previousPrice: currentPrice,     // ← Esto se usará como previous en la siguiente corrida
        asin: asin,
        productName: productName,
        savedAt: new Date().toISOString()
    }
}];

